import * as fs from 'node:fs/promises';
import {mock} from 'node:test';
import {spawnSync} from 'node:child_process';
import {AsyncLocalStorage} from 'node:async_hooks';
const base='/tmp/codex-tool-runs/svton/m2-r2-fd-review-20260930';
const dir=await fs.mkdtemp(base+'/race-'),file=dir+'/state.json',lock=file+'.lock',prev=lock+'.prev';
const dead=spawnSync(process.execPath,['-e','process.exit(0)']);
try{process.kill(dead.pid,0);throw Error('fixture PID reused')}catch(e){if(e.code!=='ESRCH')throw e;}
await fs.writeFile(lock,`${dead.pid}\tdead-owner-token\n`);
const defer=()=>{let resolve;const promise=new Promise(r=>resolve=r);return {promise,resolve}};
const aBefore=defer(),resumeA=defer(),bMoved=defer(),resumeB=defer(),aEntered=defer(),cEntered=defer(),releaseA=defer(),releaseC=defer();
const als=new AsyncLocalStorage();let aHooked=false,bHooked=false,active=0,maxActive=0,cActive=false,overwroteLiveC=false;
const {default:ignored,...named}=fs;
mock.module('node:fs/promises',{namedExports:{...named,rename:async(from,to)=>{
 if(als.getStore()==='A'&&to===lock&&!aHooked){aHooked=true;aBefore.resolve();await resumeA.promise;overwroteLiveC=cActive;}
 await fs.rename(from,to);
 if(als.getStore()==='B'&&from===prev&&!bHooked){bHooked=true;bMoved.resolve();await resumeB.promise;}
}}});
const {withFileLock}=await import('/Users/zhaoxingbo/Workspace/ai-driven/svton/shipkit/dist/shared/file-lock.js');
const guard=setTimeout(()=>{console.error('REPRO_TIMEOUT');process.exit(2)},12000);
const a=als.run('A',()=>withFileLock(file,async()=>{active++;maxActive=Math.max(maxActive,active);aEntered.resolve();await releaseA.promise;active--;},{timeoutMs:7000}));
await aBefore.promise;
const aRecord=await fs.readFile(prev,'utf8');
const b=als.run('B',()=>withFileLock(file,async()=>{active++;maxActive=Math.max(maxActive,active);active--;},{timeoutMs:7000}));
await bMoved.promise;
const prevMissingWhileALive=await fs.stat(prev).then(()=>false,e=>e.code==='ENOENT');
const c=als.run('C',()=>withFileLock(file,async()=>{cActive=true;active++;maxActive=Math.max(maxActive,active);cEntered.resolve();await releaseC.promise;active--;cActive=false;},{timeoutMs:7000}));
await cEntered.promise;const cLock=await fs.readFile(lock,'utf8');
resumeA.resolve();await aEntered.promise;
const result={maxActive,activeAtObservation:active,overwroteLiveC,cLockChanged:await fs.readFile(lock,'utf8')!==cLock,prevMissingWhileALive,aRecordPid:Number(aRecord.split('\t')[0]),actualLivePid:process.pid,onlySchedulingMocked:true};
releaseA.resolve();await a;releaseC.resolve();await c;resumeB.resolve();await b;
clearTimeout(guard);mock.restoreAll();await fs.writeFile(base+'/fd-race-result.json',JSON.stringify(result,null,2));console.log(JSON.stringify(result));
